def send_main_menu(chat_id, notification=""):

    session = get_user_session(chat_id)

    token = session.get('token')

    text = ""

    if notification:

        text += f"<b>{notification}</b>\n\n"

    if not token:

        text += "🏎️ <b>CarX Street Manager</b> 🏎️\n👑 <b>Founder:</b> @King_mingfu\n\n"

        text += "<i>Welcome. Choose an option below:</i>"

        markup = types.InlineKeyboardMarkup(row_width=1)

        markup.add(

            types.InlineKeyboardButton("🔑 Register", callback_data="mode_register"),

            types.InlineKeyboardButton("🔓 Login", callback_data="mode_login"),

            types.InlineKeyboardButton("🗑️ Delete Account", callback_data="mode_delete"),

            types.InlineKeyboardButton("⚙️ Settings", callback_data="menu_settings")

        )

    else:

        profile = session.get('profile', {}) or {}

        res = profile.get('resources', {}) or {}

        silver = res.get('soft', {}).get('amount', 0)

        gold = res.get('hard', {}).get('amount', 0)

        xp = res.get('experience', {}).get('amount', 0)

        maps = profile.get('game_world_parts', {}) or {}

        maps_unlocked = sum(1 for v in maps.values() if isinstance(v, dict) and v.get('unlocked'))

        cars_count = len(profile.get('cars', {}).get('items', {}) or {})

        streetpass = profile.get('is_pass_owned', False)

        premium = profile.get('has_premium', False)

        email = session.get('email') or "—"

        cid = session.get('carx_id') or "—"



        text += "🏎️ <b>CarX Street Control Panel</b> 🏎️\n👑 <b>Founder:</b> @King_mingfu\n\n"

        text += f"📧 <b>Account:</b> <code>{email}</code>\n"

        text += f"🆔 <b>CarX ID:</b> <code>{cid}</code>\n"

        text += "─" * 26 + "\n"

        text += f"💰 <b>Silver:</b> <code>{silver:,}</code>\n"

        text += f"💛 <b>Gold:</b> <code>{gold:,}</code>\n"

        text += f"⭐ <b>XP:</b> <code>{xp:,}</code>\n"

        text += f"🗺️ <b>Maps:</b> <code>{maps_unlocked}/6</code>\n"

        text += f"🚗 <b>Cars:</b> <code>{cars_count}</code>\n"

        text += f"🎟️ <b>Street Pass:</b> {'✅ Enabled' if streetpass else '❌ Disabled'}\n"

        text += f"👑 <b>Premium:</b> {'✅ Active' if premium else '❌ Inactive'}\n"

        text += "─" * 26 + "\n"

        text += "<i>Select an operation below.</i>"

        markup = get_main_menu_keyboard()

    send_or_edit_menu(chat_id, text, markup)



