def apply_and_save_currency(chat_id, silver, gold, xp):

    session = get_user_session(chat_id)

    if not session.get('token') or not session.get('profile'):

        send_main_menu(chat_id, "❌ Not logged in.")

        return

    temp = bot.send_message(chat_id, "⏳ Processing...")

    profile = inject_currency(session['profile'], silver, gold, xp)

    session['profile'] = profile

    ok, err = save_profile(session['token'], profile)

    try: bot.delete_message(chat_id, temp.message_id)

    except: pass

    if ok:

        send_main_menu(chat_id, "✅ Done.")

        check_and_consume_one_time_key(chat_id)

    else:

        send_main_menu(chat_id, "❌ Save failed.")




def add_cars_to_profile(chat_id, option, custom_count=None):
    session = get_user_session(chat_id)
    if not session.get('token') or not session.get('profile'):
        send_main_menu(chat_id, '❌ Not logged in.')
        return
    car_data = get_car_data()
    if not car_data:
        own = session['profile'].get('cars', {}).get('items', {})
        if own:
            car_data = own
        else:
            send_main_menu(chat_id, '❌ No car data available.')
            return
    temp = bot.send_message(chat_id, '⏳ Processing...')
    if option == 'all':
        selected = car_data
    elif option == 'random':
        num = min(10, len(car_data))
        selected = dict(random.sample(list(car_data.items()), num))
    elif option == 'first_50':
        num = min(50, len(car_data))
        selected = dict(list(car_data.items())[:num])
    else:
        num = min(custom_count, len(car_data))
        selected = dict(random.sample(list(car_data.items()), num))
        
    profile = session['profile']
    existing = profile.get('cars', {}).get('items', {})
    if not isinstance(existing, dict):
        existing = {}
    max_id = 1000
    for cid in existing:
        try:
            if int(cid) > max_id:
                max_id = int(cid)
        except:
            pass

    added = 0
    ok = True
    for _, cfg in selected.items():
        if not isinstance(cfg, dict) or not cfg.get('__desc_id'):
            continue
        max_id += 1
        existing[str(max_id)] = json.loads(json.dumps(cfg))
        profile['cars'] = {'seed': max(1000, max_id + 1), 'items': existing}
        if profile.get('current_car_id') not in existing:
            profile['current_car_id'] = next(iter(existing.keys()), '1000')
        ok, err = save_profile(session['token'], profile)
        if not ok:
            break
        added += 1

    session['profile'] = profile
    try:
        bot.delete_message(chat_id, temp.message_id)
    except:
        pass
    if ok:
        send_main_menu(chat_id, '✅ Done.')
        check_and_consume_one_time_key(chat_id)
    else:
        send_main_menu(chat_id, '❌ Save failed.')

def refresh_profile_action(chat_id):

    session = get_user_session(chat_id)

    if not session.get('token'):

        send_main_menu(chat_id, "❌ Not logged in.")

        return

    temp = bot.send_message(chat_id, "⏳ Refreshing...")

    profile, err = get_profile(session['token'])

    try: bot.delete_message(chat_id, temp.message_id)

    except: pass

    if not profile:

        send_main_menu(chat_id, "❌ Refresh failed.")

        return

    session['profile'] = profile

    send_main_menu(chat_id, "✅ Done.")



def restore_backup_action(chat_id):

    session = get_user_session(chat_id)

    if not session.get('token') or not session.get('profile'):

        send_main_menu(chat_id, "❌ Not logged in.")

        return

    if not RESTORE_FILE or not os.path.isfile(RESTORE_FILE):

        send_main_menu(chat_id, "❌ Backup file not found.")

        return

    temp = bot.send_message(chat_id, "⏳ Restoring...")

    try:

        with open(RESTORE_FILE, "r", encoding="utf-8") as f:

            backup = json.load(f)

    except Exception:

        try: bot.delete_message(chat_id, temp.message_id)

        except: pass

        send_main_menu(chat_id, "❌ Could not read backup file.")

        return

    backup["data_version"] = (backup.get("data_version", 0) or 0) + 1

    backup["messaging_version"] = backup.get("messaging_version", 1) or 1

    backup["model_upgrade_version"] = backup.get("model_upgrade_version", 1) or 1

    session['profile'] = backup

    ok, _ = save_profile(session['token'], backup)

    try: bot.delete_message(chat_id, temp.message_id)

    except: pass

    if ok:

        send_main_menu(chat_id, "✅ Successful.")

        check_and_consume_one_time_key(chat_id)

    else:

        send_main_menu(chat_id, "❌ Save failed.")



def execute_deletion(chat_id):

    session = get_user_session(chat_id)

    email = session.get('del_email') or session.get('email')

    password = session.get('del_password') or session.get('password')

    if not email or not password:

        send_main_menu(chat_id, "❌ Missing credentials.")

        return

    send_or_edit_menu(chat_id, "⏳ Processing...")

    ok, _ = delete_account_auto(email, password)

    for k in ('token', 'carx_id', 'profile', 'email', 'password',

              'del_email', 'del_password', 'step', 'last_menu_msg_id'):

        session[k] = None

    if ok:

        send_main_menu(chat_id, "✅ Successful.")

    else:

        send_main_menu(chat_id, "❌ Failed. Check credentials.")



